<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class Beneficiary extends Model { use HasUuids; public $incrementing=false; protected $keyType='string'; protected $fillable=['user_id','merchant_id','owner_type','display_name','beneficiary_type','country_code','status','verification_status','risk_status','search_name','details_fingerprint','metadata']; protected $casts=['metadata'=>'array']; public function accounts(): HasMany { return $this->hasMany(BeneficiaryAccount::class); } public function user(): BelongsTo { return $this->belongsTo(User::class); } public function isOwnedBy(User $user): bool { if($this->owner_type==='customer') return (string)$this->user_id===(string)$user->id; return \Illuminate\Support\Facades\DB::table('merchant_memberships')->where('merchant_id',$this->merchant_id)->where('user_id',$user->id)->exists(); } }
